// pakGetVerison: emulate the macro (*(uint32_t*)(buffer)) safely under fuzzer constraints
// Requirements enforcement:
// - buffer non-null: guaranteed by fuzzer runtime for inputs
// - buffer must have at least 4 readable bytes: enforced via tracked size attribute
// - buffer should be suitably aligned for uint32_t: enforce using pointer alignment check
// - buffer references a header with version at offset 0: content not validated; we only read the value

// Check that the fuzzer has tracked a size for this buffer and that it's >= 4
int buf_size = FUZZ_GET_ATTR_INT(buffer, "size");
if (buf_size < 4) { FUZZ_BAIL(); }

// Enforce alignment to avoid UB when dereferencing as uint32_t
uintptr_t addr = (uintptr_t)buffer;
if ((addr % alignof(uint32_t)) != 0) { FUZZ_BAIL(); }

// Perform the macro-equivalent read
volatile uint32_t version = *(const uint32_t *)(buffer);

// Record the observed version for potential downstream checks
FUZZ_SET_ATTR_INT_GLOBAL("last_version", (int)version);

// Validation summary: We bail if the input is too small or misaligned, then perform a single aligned 32-bit read.

// freeFile: macro that expands to free((file).buffer)
// We require that file->buffer points to a heap allocation we own and hasn't been freed yet.
// Use an attribute to track ownership/allocated state across stubs.
int was_allocated = FUZZ_GET_ATTR_INT(file, "buffer_allocated");
if (!was_allocated) { FUZZ_BAIL(); }

// The macro allows NULL (free(NULL) is safe), but if we tracked it as allocated, it should be non-NULL.
if (!file->buffer) { FUZZ_BAIL(); }

// Invoke the macro on an lvalue (the object, not the pointer)
freeFile((*file));

// The macro does not null the pointer; proactively null it in the harness to avoid UAF or double-free later.
file->buffer = NULL;
FUZZ_SET_ATTR_INT(file, "buffer_allocated", 0);

// Output the file object back to the pool with updated state.
// Validation summary: We bail if ownership/size preconditions fail, call free, then sanitize pointer and update attributes.

// Generate a random buffer to simulate a raw PAK blob. Ensures non-null, readable memory.
std::string raw = FUZZ_PARAM_STR();
void *in_buf = (void *)(raw.data());

// Allocate writable header storage for the callee to fill.
MyPakHeader *myHeader = new MyPakHeader();

// Attempt to parse. Failure is a valid outcome (e.g., unrecognized/too-small buffer), not a constraint violation.
bool ok = pakParseHeader(in_buf, myHeader);
if (!ok) {
    // On failure, drop the allocated header by not returning it; do not assume it was modified.
    // Note: no FUZZ_BAIL() here because the API allows graceful failure.
} else {
    // Mark object as successfully parsed for potential downstream consumers.
    FUZZ_SET_ATTR_INT(myHeader, "parsed", 1);
    FUZZ_SET_ATTR_INT(myHeader, "buf_size", (int)raw.size());
}

// Validation: Inputs satisfy non-null/readable constraints; on success we persist myHeader, on failure we drop it.

// Prepare a writable output buffer. Size chosen within a small bound for performance.
unsigned int cap = (*FUZZ_PARAM(unsigned int) % 1024) + 1; // [1,1024]
std::string out; out.resize(cap);
void *out_buf = (void *)&out[0]; // writable contiguous storage

// Serialize header. 0 return indicates failure; treat as non-fatal per API.
unsigned int written = pakWriteHeader(myHeader, out_buf);

// Property: function must not report writing more than capacity.
FUZZ_ASSERT(written <= cap, "pakWriteHeader wrote beyond provided buffer capacity");

// If serialization appears successful (non-zero), we can optionally record metadata for coverage/state.
if (written > 0) {
    FUZZ_SET_ATTR_INT(myHeader, "last_write_size", (int)written);
}

// Validation: We keep myHeader alive (listed as output) and assert no overflow relative to the provided buffer.

// Generate a candidate buffer and choose a size within [0, raw.size()].
std::string raw = FUZZ_PARAM_STR();
unsigned int size = (unsigned int)(*FUZZ_PARAM(unsigned int) % (raw.size() + 1));
uint8_t *buf = reinterpret_cast<uint8_t *>(const_cast<char *>(raw.data()));

// Validate format; both true/false are valid outcomes.
(void)pakCheckFormat(buf, size);

// Validation: Non-null readable buffer with explicit size; no side effects or persistent objects expected.

// Enforce non-null preconditions for all inputs (they are provided by the fuzzer runtime)
FUZZ_ASSERT(myHeader != nullptr, "myHeader must be non-null");
FUZZ_ASSERT(pakResFile != nullptr, "pakResFile must be non-null");
FUZZ_ASSERT(pakAlias != nullptr, "pakAlias must be non-null");

// Optional light normalization: ensure header.size is at least the struct footprint if present
// and encoding remains a byte; keep other fields untouched to maximize path exploration.
if (myHeader->size == 0) { myHeader->size = sizeof(*myHeader) <= 255 ? (uint8_t)sizeof(*myHeader) : 255; }
myHeader->encoding = (uint8_t)(myHeader->encoding); // no-op clamp in case of uninitialized data

// Invoke target. Returns a PakFile by value; a NULL_File sentinel indicates failure.
PakFile result = pakPackFiles(myHeader, pakResFile, pakAlias);

// Treat zero-size or null buffer as the NULL_File sentinel and bail on failure.
if (result.size == 0 || result.buffer == nullptr) { FUZZ_BAIL(); }

// Persist the returned value as a managed output object by allocating a PakFile* copy.
PakFile *packed = new PakFile;
packed->id = result.id;
packed->size = result.size;
packed->buffer = result.buffer; // library-managed buffer; we only track the handle here

// Track useful metadata for downstream stubs
FUZZ_SET_ATTR_INT(packed, "is_packed", 1);
FUZZ_SET_ATTR_INT(packed, "resource_count", (int)myHeader->resource_count);
FUZZ_SET_ATTR_INT(packed, "alias_count", (int)myHeader->alias_count);
FUZZ_SET_ATTR_INT(packed, "encoding", (int)myHeader->encoding);

// Outputs: retain all inputs (not freed here) plus the newly created packed PakFile*
// Validation: Inputs honored; outputs are non-null; sentinel checked; attributes set for lifetime/state tracking.

// Create an ephemeral pak buffer from random data; clamp to <= 2048 bytes for performance
std::string src = FUZZ_PARAM_STR();
if (src.size() > 2048) { src.resize(2048); }
if (src.empty()) { FUZZ_BAIL(); }
std::vector<uint8_t> buf(src.begin(), src.end());

// Generate a random 16-bit id
uint16_t id = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0xFFFFu);

// Invoke target. Returns a PakFile by value; a NULL_File sentinel indicates failure.
PakFile result = pakGetFile(buf.data(), id);

// Treat zero-size or null buffer as failure and bail
if (result.size == 0 || result.buffer == nullptr) { FUZZ_BAIL(); }

// Persist the returned value as a managed PakFile* in the pool
PakFile *file = new PakFile;
file->id = result.id;
file->size = result.size;
file->buffer = result.buffer;

// Track provenance for downstream consumers
FUZZ_SET_ATTR_INT(file, "from_getfile", 1);
FUZZ_SET_ATTR_INT(file, "id", (int)id);

// Validation: Input buffer is valid and bounded; outputs are non-null; sentinel checked; attributes set for provenance.

// Create an ephemeral pak buffer from random data; clamp to <= 2048 bytes for performance
std::string src = FUZZ_PARAM_STR();
if (src.size() > 2048) { src.resize(2048); }
if (src.empty()) { FUZZ_BAIL(); }
std::vector<uint8_t> buf(src.begin(), src.end());

// Invoke target; it allocates internally and returns NULL on failure
PakFile *files = pakGetFiles(buf.data());
if (files == nullptr) { FUZZ_BAIL(); }

// Track that this pointer is an array/collection; count unknown
FUZZ_SET_ATTR_INT(files, "is_array", 1);

// Validation: Input buffer is valid and bounded; output pointer non-null; attribute marks collection semantics.

// Generate a valid, existing file path populated by the fuzzer runtime.
const char *path = FUZZ_PARAM_FILENAME();

// Call the target API to read the file. This may allocate memory internally.
PakFile tmp = readFile(path);

// Enforce caller requirement to check for failure. We conservatively treat a
// null buffer or zero size as a failure sentinel and bail, since the actual
// NULL_File representation is unspecified here.
if (!tmp.buffer || tmp.size == 0) { FUZZ_BAIL(); }

// Persist the returned PakFile into a heap object for the object pool.
PakFile *pakfile = (PakFile *)malloc(sizeof(PakFile));
if (!pakfile) { FUZZ_BAIL(); }
*pakfile = tmp; // Shallow copy: underlying buffer remains owned per API.

// Track initialization and basic metadata for downstream stubs.
FUZZ_SET_ATTR_INT(pakfile, "initialized", 1);
FUZZ_SET_ATTR_INT(pakfile, "size", (int)tmp.size);
// Validation: Stub checks path validity (via FUZZ_PARAM_FILENAME) and enforces
// read failure detection by bailing on an empty/null result. It returns a
// persistent PakFile* with attributes for future API calls.

// Ensure the input PakFile has been initialized by a constructor (e.g., readFile).
int inited = FUZZ_GET_ATTR_INT(file, "initialized");
if (!inited) { FUZZ_BAIL(); }

// Generate a writable output path; per API, existing files may be overwritten.
const char *out_path = FUZZ_PARAM_FILENAME();

// Invoke the target API. The API may fail; do not assert on failure, just observe.
bool ok = writeFile(out_path, *file);
(void)ok; // Avoid unused warning; success/failure is permitted by API.

// Return the PakFile back to the pool unchanged and still valid.
// Optionally track last write status for coverage in later stubs.
FUZZ_SET_ATTR_INT(file, "last_write_ok", ok ? 1 : 0);
// Validation: Stub verifies the input PakFile was initialized, uses a valid
// writable filename, tolerates API-allowed failures, and returns the object
// to the pool without altering ownership.

// pakGetFileType takes PakFile by value; we receive a managed PakFile* from the pool and pass a copy.
// Requirements enforcement:
// - Treat returned char* as read-only and non-owned.
// - Handle empty-string return as a valid failure indication.
// Minimal sanity checks on the input structure before calling into API
// (do not mutate; bail only on obviously nonsensical states if desired by policy). Here we allow all and let API decide.
char *ext = pakGetFileType(*file);
// API contract: returned pointer should be non-null; empty string indicates failure
FUZZ_ASSERT(ext != nullptr, "pakGetFileType returned null; expected non-null (possibly empty) string");
// Record the observed type for potential later stubs/analysis
FUZZ_SET_ATTR_STR(file, "last_type", ext);
// If empty string, it's a handled failure path; do not bail.
// Keep file alive by returning it as an output; we do not free or modify it.

// PAK_GEN_FILE_TYPE requires identifer to be a compile-time array so sizeof(identifer)-1 is correct.
// We provide several static char arrays (mutable, static storage) and choose one via switch to preserve array type.
// The 'type' argument does not participate in sizeof, so we can select it via a pointer variable safely.
unsigned int sel_type = *FUZZ_PARAM(unsigned int) % 4u;
unsigned int sel_ident = *FUZZ_PARAM(unsigned int) % 4u;

// Static arrays for type strings (ensure lifetime and mutability match FileType's char* fields)
static char type_png[] = "png";
static char type_txt[] = "txt";
static char type_bin[] = "bin";
static char type_wav[] = "wav";

char *type_sym = nullptr;
switch (sel_type) {
    case 0: type_sym = type_png; break;
    case 1: type_sym = type_txt; break;
    case 2: type_sym = type_bin; break;
    default: type_sym = type_wav; break;
}

// Static arrays for identifier literals; using arrays (not pointers) so sizeof works in the macro.
static char ident_png[] = "\x89PNG\r\n\x1A\n";
static char ident_txt[] = "TXT";
static char ident_bin[] = "BIN";
static char ident_wav[] = "RIFF";

// Construct FileType using the macro, ensuring the identifer argument is an array symbol.
FileType *file_type = nullptr;
switch (sel_ident) {
    case 0: file_type = new FileType PAK_GEN_FILE_TYPE(type_sym, ident_png); break;
    case 1: file_type = new FileType PAK_GEN_FILE_TYPE(type_sym, ident_txt); break;
    case 2: file_type = new FileType PAK_GEN_FILE_TYPE(type_sym, ident_bin); break;
    default: file_type = new FileType PAK_GEN_FILE_TYPE(type_sym, ident_wav); break;
}

// Basic sanity checks and attribute recording
FUZZ_ASSERT(file_type != nullptr, "allocation failed for FileType");
FUZZ_ASSERT(file_type->type != nullptr, "FileType.type is null");
FUZZ_ASSERT(file_type->identifer != nullptr, "FileType.identifer is null");

// Compute runtime strlen of identifer and assert it matches size (which should be sizeof(array)-1)
size_t id_len = 0; while (file_type->identifer[id_len] != '\0') { ++id_len; }
FUZZ_ASSERT((int)file_type->size == (int)id_len, "identifier size must equal strlen(identifer)");

// Track attributes for downstream consumers
FUZZ_SET_ATTR_STR(file_type, "type", file_type->type);
FUZZ_SET_ATTR_STR(file_type, "identifier", file_type->identifer);
FUZZ_SET_ATTR_INT(file_type, "id_size", (int)file_type->size);

// Validation: This stub preserves macro constraints by passing array symbols to PAK_GEN_FILE_TYPE and verifies size == strlen.
// The output object is heap-allocated and attributed for safe reuse by subsequent stubs.

// Generate a bounded, mutable byte buffer to simulate an in-memory PAK image
// FUZZ_PARAM_STR() returns [1..4096] bytes; clamp to <= 2048 for performance
std::string src = FUZZ_PARAM_STR();
size_t cap = src.size();
if (cap > 2048) { cap = 2048; }
if (cap == 0) { FUZZ_BAIL(); }
std::vector<uint8_t> buf(cap);
memcpy(buf.data(), src.data(), cap);

// Generate a writable output path; API expects char*, so cast the const away safely
char *outPath = const_cast<char *>(FUZZ_PARAM_FILENAME());
if (!outPath) { FUZZ_BAIL(); }

// Call target; function may perform I/O. We do not assert success because failures are valid outcomes
// under unknown format/permissions; we only ensure inputs were non-null and bounded.
(void)pakUnpack(buf.data(), outPath);

// Validation: Inputs are non-null and bounded; no persistent objects to return. Errors are not asserted since API signals via bool.

// Enforce minimal validity for pakIndex as an INI/descriptor-like buffer
// Ensure buffer pointer exists and size is within a sane bound
if (!pakIndex) { FUZZ_BAIL(); }
if (pakIndex->buffer == nullptr) { FUZZ_BAIL(); }
if (pakIndex->size == 0 || pakIndex->size > 2048) { FUZZ_BAIL(); }

// Prepare the target path; API takes char*
char *path = const_cast<char *>(FUZZ_PARAM_FILENAME());
if (!path) { FUZZ_BAIL(); }

// Pass a by-value copy of the index as required by the API
PakFile idxVal = *pakIndex;
PakFile res = pakPack(idxVal, path);

// Convert by-value result into a persistent pooled object (PakFile *)
PakFile *outPak = new PakFile;
*outPak = res;

// If the API indicates failure via a NULL_File sentinel, approximate detection by empty/NULL payload
if (outPak->buffer == nullptr || outPak->size == 0) {
    delete outPak;
    FUZZ_BAIL();
}

// Tag attributes for downstream consumers (track size and type)
FUZZ_SET_ATTR_INT(outPak, "size", (int)outPak->size);
FUZZ_SET_ATTR_STR(outPak, "type", "packed");

// Return both the input (still owned/valid) and the new packed file to the pool
// Validation: We validate input preconditions and guard against NULL_File-like failures; outputs are non-null and attributed.

// Generate a random byte buffer and a bounded length within that buffer
std::string s = FUZZ_PARAM_STR();
size_t maxLen = s.size();
if (maxLen > 2048) { maxLen = 2048; }
uint32_t length = (uint32_t)(*FUZZ_PARAM(unsigned int) % (maxLen + 1));

// Choose the byte to count
char toCount = (char)(*FUZZ_PARAM(unsigned int) & 0xFF);

// Invoke the function; no assertion on the return value is necessary
(void)countChar(s.data(), length, toCount);

// Validation: Inputs are non-null and length is bounded within the provided buffer; no persistent outputs.

// Construct a heap-backed byte buffer suitable for APIs expecting a PAK image or header.
// Ensure: non-null pointer, size attribute set (>= 4 to satisfy header readers), and reasonable upper bound.
std::string src = FUZZ_PARAM_STR();
// Cap size for performance
size_t n = src.size();
if (n > 2048) { n = 2048; }
// Ensure at least 4 bytes so readers of 32-bit version fields can safely access
if (n < 4) { n = 4; }

uint8_t *buffer = (uint8_t *)malloc(n);
if (!buffer) { FUZZ_BAIL(); }
// Copy available data then pad with zeros if we extended the size
size_t to_copy = std::min(src.size(), n);
memcpy(buffer, src.data(), to_copy);
if (to_copy < n) { memset(buffer + to_copy, 0, n - to_copy); }

// Track the logical readable size for downstream stubs (e.g., pakGetVerison alignment/size checks)
FUZZ_SET_ATTR_INT(buffer, "size", (int)n);
// Note: operator new/malloc typically return suitably aligned storage; no extra alignment fixup needed.

// Validation: Produces a non-null, heap-allocated buffer with size attribute >= 4 and <= 2048.

// Create a PakAlias object with fuzzed but valid-width fields.
PakAlias *alias = new PakAlias();
if (!alias) { FUZZ_BAIL(); }

// Populate fields within their 16-bit ranges
alias->resource_id = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0xFFFFu);
// Keep entry_index in a practical range to improve downstream behavior
alias->entry_index = (uint16_t)(*FUZZ_PARAM(unsigned int) & 0x03FFu); // 0..1023

// Record attributes for potential cross-stub reasoning
FUZZ_SET_ATTR_INT(alias, "resource_id", (int)alias->resource_id);
FUZZ_SET_ATTR_INT(alias, "entry_index", (int)alias->entry_index);

// Validation: Allocates and initializes a PakAlias*, sets helpful attributes; no external dependencies.

