import random
import struct
from typing import List

# This generator targets functions operating on arbitrary byte buffers, specifically countChar.
# Strategy:
# - Produce a bytes buffer up to 2048 bytes, since the fuzzer caps length to 2048.
# - Include patterns that are interesting for counting: repeats, alternating bytes, gradients,
#   zero bytes, high-ASCII, and embedded sequences that might stress SIMD or unrolled loops.
# - Randomly select a target byte and ensure it appears with varying frequencies (0, 1, many).
# - Keep total size <= 4096 bytes as required (we cap to 2048).

MAX_FUZZ_LEN = 2048

def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))

def _pattern_repeat(byte_val: int, count: int) -> bytes:
    return bytes([byte_val]) * count

def _pattern_alternating(a: int, b: int, n: int) -> bytes:
    if n <= 0:
        return b""
    arr = bytearray(n)
    for i in range(n):
        arr[i] = a if (i & 1) == 0 else b
    return bytes(arr)

def _pattern_gradient(start: int, step: int, n: int) -> bytes:
    if n <= 0:
        return b""
    arr = bytearray(n)
    v = start & 0xFF
    for i in range(n):
        arr[i] = v
        v = (v + step) & 0xFF
    return bytes(arr)

def _pattern_blocks(val: int, other: int, n: int, block: int) -> bytes:
    if n <= 0:
        return b""
    if block <= 0:
        block = 1
    arr = bytearray(n)
    cur = val
    i = 0
    while i < n:
        take = min(block, n - i)
        for j in range(take):
            arr[i + j] = cur
        i += take
        cur = other if cur == val else val
    return bytes(arr)

def _insert_occurrences(rng: random.Random, buf: bytearray, target: int, occurrences: int) -> None:
    # Ensure target occurs 'occurrences' times by overwriting positions.
    n = len(buf)
    if n == 0 or occurrences <= 0:
        return
    positions = set()
    for _ in range(occurrences):
        pos = rng.randrange(0, n)
        positions.add(pos)
    for pos in positions:
        buf[pos] = target

def _compose_chunks(chunks: List[bytes], limit: int) -> bytes:
    out = bytearray()
    for c in chunks:
        if not c:
            continue
        remaining = limit - len(out)
        if remaining <= 0:
            break
        if len(c) <= remaining:
            out.extend(c)
        else:
            out.extend(c[:remaining])
            break
    return bytes(out)

def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose total length up to 2048, with a bias to interesting sizes
    interesting_sizes = [0, 1, 2, 3, 7, 8, 15, 16, 31, 32, 63, 64, 127, 128, 255, 256, 511, 512, 1023, 1024, 1500, 2047, 2048]
    if rng.random() < 0.7:
        total_len = interesting_sizes[rng.randrange(len(interesting_sizes))]
    else:
        total_len = rng.randrange(0, MAX_FUZZ_LEN + 1)

    # Pick a target byte that the harness will count later; we don't know it here,
    # but we can embed diverse candidates. We'll also bias common values.
    common_bytes = [0x00, 0x20, 0x2F, 0x30, 0x39, 0x41, 0x5A, 0x61, 0x7A, 0x7F, 0xFF]
    target_candidates = list({rng.randrange(256) for _ in range(5)} | set(common_bytes))

    # Build multiple chunks with differing patterns
    chunks: List[bytes] = []

    # Repeated target candidate blocks
    rep_byte = target_candidates[rng.randrange(len(target_candidates))]
    rep_len = rng.randint(0, max(0, total_len // 3)) if total_len > 0 else 0
    chunks.append(_pattern_repeat(rep_byte, rep_len))

    # Alternating pattern
    a = target_candidates[rng.randrange(len(target_candidates))]
    b = target_candidates[rng.randrange(len(target_candidates))]
    if a == b:
        b = (b + 1) & 0xFF
    alt_len = rng.randint(0, max(0, total_len // 3)) if total_len > 0 else 0
    chunks.append(_pattern_alternating(a, b, alt_len))

    # Gradient pattern
    grad_len = rng.randint(0, max(0, total_len // 2)) if total_len > 0 else 0
    chunks.append(_pattern_gradient(rng.randrange(256), rng.choice([1, 3, 5, 17, 63, 127, 255]), grad_len))

    # Block pattern
    block_len = rng.randint(0, max(0, total_len // 2)) if total_len > 0 else 0
    chunks.append(_pattern_blocks(rng.randrange(256), rng.randrange(256), block_len, rng.choice([1, 2, 4, 8, 16, 32])))

    # Random tail to reach desired length
    composed = bytearray(_compose_chunks(chunks, total_len))
    if len(composed) < total_len:
        composed.extend(_rand_bytes(rng, total_len - len(composed)))

    # Ensure some specific occurrences for a random candidate byte to exercise 0/1/many cases
    if total_len > 0:
        ensured_byte = target_candidates[rng.randrange(len(target_candidates))]
        case = rng.random()
        if case < 0.33:
            # Zero occurrences: overwrite any with a non-matching value by flipping ensured_byte
            # We cannot ensure zero without scanning; we can reduce likelihood by replacing some.
            for i in range(len(composed)):
                if composed[i] == ensured_byte and rng.random() < 0.8:
                    composed[i] = (ensured_byte + 1) & 0xFF
        elif case < 0.66:
            # Exactly one (best-effort): clear many, set one
            pos = rng.randrange(len(composed))
            for i in range(len(composed)):
                if i != pos and composed[i] == ensured_byte and rng.random() < 0.8:
                    composed[i] = (ensured_byte ^ 0xFF)
            composed[pos] = ensured_byte
        else:
            # Many occurrences: insert some occurrences
            _insert_occurrences(rng, composed, ensured_byte, rng.randint(2, max(2, min(64, total_len // 8))))

    # Occasionally prepend small headers or magic-like bytes to diversify content
    if total_len >= 8 and rng.random() < 0.3:
        header_choice = rng.randrange(4)
        if header_choice == 0:
            # Little-endian uint32 version-like field + encoding byte
            ver = rng.choice([4,5,0,0xFFFFFFFF])
            enc = rng.randrange(256)
            prefix = struct.pack('<I', ver) + bytes([enc, 0, 0, 0])
        elif header_choice == 1:
            # ASCII tag
            tag = rng.choice([b'PAK5', b'PAK4', b'PK\x03\x04', b'\x89PNG'])
            prefix = tag
        elif header_choice == 2:
            # Size-prefixed block
            sz = min(len(composed), 1024)
            prefix = struct.pack('<I', sz)
        else:
            # Repeating zero header
            prefix = b"\x00\x00\x00\x00\x00\x00\x00\x00"
        # Integrate prefix without exceeding total_len
        take = min(len(prefix), total_len)
        composed[:take] = prefix[:take]

    # Ensure length limit and type
    if len(composed) > MAX_FUZZ_LEN:
        composed = composed[:MAX_FUZZ_LEN]

    return bytes(composed)
